// Requires Node's WebSocket: run scenarios with `node --experimental-websocket`.
import { spawn } from 'node:child_process';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function connect(port) {
  for (let i = 0; i < 60; i++) {
    try {
      const targets = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
      const page = targets.find((t) => t.type === 'page');
      if (page) {
        const ws = new WebSocket(page.webSocketDebuggerUrl);
        await new Promise((resolve, reject) => {
          ws.addEventListener('open', resolve);
          ws.addEventListener('error', reject);
        });
        return ws;
      }
    } catch {
      // app not up yet
    }
    await sleep(500);
  }
  throw new Error(`No Electron page on port ${port}`);
}

export async function withApp({ dataDir, port = 9361 }, fn) {
  const env = { ...process.env };
  delete env.NODE_OPTIONS; // Electron rejects --openssl-legacy-provider
  const electronBin = path.join(root, 'node_modules', '.bin', 'electron');
  const child = spawn(electronBin, ['.', `--remote-debugging-port=${port}`, `--user-data-dir=${dataDir}`], {
    cwd: root,
    env,
    stdio: ['ignore', 'ignore', 'ignore'],
  });
  const exited = new Promise((r) => child.on('exit', r));

  let ws;
  try {
    ws = await connect(port);
    let nextId = 1;
    const send = (method, params) =>
      new Promise((resolve) => {
        const id = nextId++;
        ws.addEventListener('message', function onMsg(ev) {
          const msg = JSON.parse(ev.data);
          if (msg.id === id) {
            ws.removeEventListener('message', onMsg);
            resolve(msg);
          }
        });
        ws.send(JSON.stringify({ id, method, params }));
      });

    const evaluate = async (expression) => {
      const msg = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true });
      if (msg.result?.exceptionDetails) {
        const d = msg.result.exceptionDetails;
        throw new Error(`In-page error: ${d.exception?.description ?? d.text}`);
      }
      return msg.result?.result?.value;
    };

    const waitFor = async (expression, timeoutMs = 10000) => {
      const start = Date.now();
      while (Date.now() - start < timeoutMs) {
        try {
          if (await evaluate(expression)) return true;
        } catch {
          // page navigating
        }
        await sleep(100);
      }
      throw new Error(`Timed out waiting for: ${expression}`);
    };

    const ready = `document.readyState === 'complete' && typeof window.knowledgeBase === 'object' && !!document.querySelector('header')`;
    await waitFor(ready);

    const reload = async () => {
      await send('Runtime.evaluate', { expression: 'location.reload()' });
      await sleep(300);
      await waitFor(ready);
    };

    return await fn({ evaluate, waitFor, reload, send });
  } finally {
    ws?.close();
    child.kill();
    await exited; // the profile lock must be released before a restart
  }
}

// Helpers injected into the page to drive the UI like a user would.
export const pageHelpers = `
  window.__e2e = {
    byLabel: (label) => Array.from(document.querySelectorAll('[aria-label="' + label + '"]')),
    setInput: (el, value) => {
      const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set;
      setter.call(el, value);
      el.dispatchEvent(new Event('input', { bubbles: true }));
    },
    sleep: (ms) => new Promise((r) => setTimeout(r, ms)),
  };
  true;
`;

export function report(name, checks) {
  let failed = 0;
  for (const [label, ok, detail] of checks) {
    if (!ok) failed++;
    console.log(`${ok ? 'PASS' : 'FAIL'}  ${label}${detail !== undefined ? `  -> ${JSON.stringify(detail)}` : ''}`);
  }
  console.log(failed ? `${name}: ${failed} check(s) FAILED` : `${name}: all ${checks.length} checks passed`);
  if (failed) process.exitCode = 1;
}

