# Retrieval Plan

## Overview

This document outlines the strategy for implementing text retrieval in the knowledge base application. The goal is to enable grounded question answering over imported documents without requiring an external LLM API.

## Chunking Approach

Documents are split into chunks using a paragraph-aware algorithm:
- Split on double newlines (paragraph boundaries)
- Merge short paragraphs until chunk reaches ~500 characters
- Each chunk gets a unique ID, document reference, and metadata

## Keyword Matching

The retrieval system uses keyword-based matching:
1. Tokenize the 
// E2E for feature conversation-history, against the built app (run `npm run build` first).
// Usage: node --experimental-websocket scripts/e2e/conversation-history.mjs
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { withApp, pageHelpers, report } from './app-session.mjs';

const dataDir = fs.mkdtempSync(path.join(os.tmpdir(), 'kb-e2e-conversation-'));
const docs = ['design-notes.md', 'retrieval-plan.md'].map((f) => path.resolve('data/sample-documents', f));
const questions = ['What is the architecture design?', 'How does retrieval work?'];
const checks = [];

// Reads the conversation as rendered.
const readConversation = `(() => [...document.querySelectorAll('[data-exchange]')].map((li) => ({
  question: li.querySelector('[data-question]')?.innerText,
  answer: li.querySelector('[data-answer-id]')?.innerText.split('\\n')[0],
  confidence: li.querySelector('[role=meter]')?.getAttribute('aria-valuetext'),
  citationToggles: li.querySelectorAll('[data-citation] button[aria-expanded]').length,
  excerptsVisible: li.querySelectorAll('[data-citation-excerpt]').length,
  helpful: li.querySelectorAll('[aria-label="Mark answer helpful"]').length,
})))()`;

const expandAndRead = `(async () => {
  const out = [];
  for (const li of document.querySelectorAll('[data-exchange]')) {
    const toggle = li.querySelector('[data-citation] button[aria-expanded]');
    toggle.click();
    await __e2e.sleep(50);
    const excerpt = li.querySelector('[data-citation-excerpt]');
    out.push({ expanded: toggle.getAttribute('aria-expanded'), controlsMatch: excerpt?.id === toggle.getAttribute('aria-controls'), excerpt: excerpt?.innerText.slice(0, 60) });
    toggle.click();
    await __e2e.sleep(50);
    out[out.length - 1].collapsedAgain = !li.querySelector('[data-citation-excerpt]');
  }
  return out;
})()`;

const checkRendered = (label, conv) => {
  checks.push([`${label}: both exchanges render in order`,
    conv.length === 2 && conv[0].question === questions[0] && conv[1].question === questions[1], conv.map((c) => c.question)]);
  checks.push([`${label}: every answer has citations, collapsed by default`,
    conv.every((c) => c.citationToggles > 0 && c.excerptsVisible === 0), conv.map((c) => [c.citationToggles, c.excerptsVisible])]);
  checks.push([`${label}: every answer has a confidence indicator`,
    conv.every((c) => /confidence \(\d+%\)/.test(c.confidence ?? '')), conv.map((c) => c.confidence)]);
};

try {
  await withApp({ dataDir }, async ({ evaluate, waitFor, reload }) => {
    await evaluate(pageHelpers);
    for (const d of docs) await evaluate(`window.knowledgeBase.documents.import(${JSON.stringify(d)})`);
    await evaluate(`window.knowledgeBase.indexing.start()`);
    const empty = await evaluate(`document.body.innerText.includes('No questions yet')`);
    checks.push(['empty conversation shows an empty state', empty]);

    // Ask both questions through the question box, like a user.
    for (const [i, q] of questions.entries()) {
      await evaluate(`(() => { __e2e.setInput(__e2e.byLabel('Ask a question')[0], ${JSON.stringify(q)}); document.querySelector('form').requestSubmit(); return true; })()`);
      await waitFor(`document.querySelectorAll('[data-exchange]').length === ${i + 1} && !document.querySelector('[role=status]')`);
    }
    checkRendered('before reload', await evaluate(readConversation));

    await reload();
    await evaluate(pageHelpers);
    await waitFor(`document.querySelectorAll('[data-exchange]').length === 2`);
    checkRendered('after reload', await evaluate(readConversation));
    const expanded = await evaluate(expandAndRead);
    checks.push(['after reload: each citation expands to show its excerpt and collapses again',
      expanded.length === 2 && expanded.every((e) => e.expanded === 'true' && e.controlsMatch && e.excerpt?.length > 0 && e.collapsedAgain), expanded]);
    const history = await evaluate(`window.knowledgeBase.qa.history()`);
    checks.push(['shown excerpt is the stored citation excerpt',
      expanded[0].excerpt === history[0].response.citations[0].excerpt.slice(0, 60), [expanded[0].excerpt, history[0].response.citations[0].excerpt.slice(0, 60)]]);

    // Selecting a document switches view; the Conversation button returns to it.
    await evaluate(`[...document.querySelectorAll('div')].find((d) => d.innerText === 'design-notes' && d.style.fontWeight === '500').click(); true`);
    await waitFor(`!document.querySelector('[data-exchange]') && document.body.innerText.includes('Filename: design-notes.md')`);
    await evaluate(`[...document.querySelectorAll('header button')].find((b) => b.textContent === 'Conversation').click(); true`);
    await waitFor(`document.querySelectorAll('[data-exchange]').length === 2`);
    checks.push(['document view and back to the conversation', true]);
  });

